const toast=t=>{const e=document.querySelector('.toast');e.textContent=t;e.classList.add('visible');setTimeout(()=>e.classList.remove('visible'),2500)};
document.querySelector('.menu')?.addEventListener('click',e=>{const nav=document.querySelector('#navigation');nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',nav.classList.contains('open'))});
document.querySelector('.motion-toggle')?.addEventListener('click',e=>{document.body.classList.toggle('paused');const p=document.body.classList.contains('paused');e.currentTarget.textContent=p?'恢复背景动画':'暂停背景动画';e.currentTarget.setAttribute('aria-pressed',p)});
document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('优惠码已复制')}catch{const x=document.createElement('textarea');x.value=b.dataset.copy;document.body.append(x);x.select();const ok=document.execCommand('copy');x.remove();toast(ok?'优惠码已复制':'请手动选择优惠码复制')}}));
const filter=()=>{const q=(document.querySelector('[data-filter]')?.value||'').toLowerCase(),t=document.querySelector('#topic-filter')?.value||'';let n=0;document.querySelectorAll('[data-search]').forEach(e=>{e.hidden=!e.dataset.search.toLowerCase().includes(q)||(t&&e.dataset.topic!==t);if(!e.hidden)n++});const c=document.querySelector('[data-count]');if(c)c.textContent=`${n} 个结果`};
document.querySelector('[data-filter]')?.addEventListener('input',filter);document.querySelector('#topic-filter')?.addEventListener('change',filter);
const script=document.currentScript||[...document.scripts].find(s=>s.src.endsWith('/site.js'));const base=new URL('./',script.src);let promise;const data=()=>promise??=fetch(new URL('site-data.json',base)).then(r=>{if(!r.ok)throw Error('资料读取失败');return r.json()});
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const href=p=>new URL('../'+p,base).href;
document.querySelector('#search-form')?.addEventListener('submit',async e=>{e.preventDefault();try{const d=await data(),q=document.querySelector('#query').value.trim().toLowerCase();const list=[...d.brands.map(b=>({title:b.name,description:b.summary,path:'brands/'+b.id+'/'})),...d.articles,...d.topics.map(t=>({title:t.name,description:t.desc,path:t.path}))].filter(x=>(x.title+' '+x.description).toLowerCase().includes(q));document.querySelector('#search-count').textContent=`找到 ${list.length} 个结果`;document.querySelector('#search-results').innerHTML=list.map(x=>`<article class="story"><h3><a href="${href(x.path)}">${E(x.title)}</a></h3><p>${E(x.description)}</p></article>`).join('')}catch{toast('搜索资料读取失败，请刷新后重试')}});
async function compare(){try{const d=await data(),ids=[...document.querySelectorAll('[data-compare-select]')].map(s=>s.value).filter(Boolean),unique=[...new Set(ids)];document.querySelector('#compare-result').innerHTML=unique.map(id=>{const b=d.brands.find(b=>b.id===id);return `<article class="brand-card"><h3><a href="${href('brands/'+b.id+'/')}">${E(b.name)}</a></h3><p>${E(b.line)}</p><p>优惠码：${E(b.coupon||'未提供')}</p>${b.plans.map(p=>`<div class="notice"><b>${E(p.name)} · ¥${p.price} / ${E(p.cycle)}</b><br>${p.quotaPeriod==='unknown'?E(p.quotedGb)+' GB · 重置待核实':p.quotaPeriod==='year-total'?E(p.quotedGb??p.gb)+' GB / 年度总额':E(p.gb??'待核实')+' GB / '+(p.quotaPeriod==='month'?'月':'总额度')}${p.capacityConflict?'<br>容量标注有差异':''}<br>原始日期：${E(p.sourceDate||'未记录')}</div>`).join('')}<a class="button" href="${href('brands/'+b.id+'/')}">完整品牌档案 ↗</a></article>`}).join('')}catch{toast('对比资料读取失败，请刷新后重试')}}document.querySelectorAll('[data-compare-select]').forEach(s=>s.addEventListener('change',compare));
